select case when sqft >= 12454 then 'high' when sqft >= 4576 then 'mid' else 'low' end sqft_bucket, month(opened_date) opened_month, sum(case when region = 'East' then sqft else 0 end) east_sqft, sum(case when region = 'South' then sqft else 0 end) south_sqft from stores group by case when sqft >= 12454 then 'high' when sqft >= 4576 then 'mid' else 'low' end, month(opened_date) order by 3 desc;
